// Business rules for stall-sharing (ghép chuồng) and ride-sharing (ghép chuyến) feasibility
// These rules evaluate whether a stall configuration or ride-share is feasible
// based on horse data, asset capacity, temperament compatibility, and timing.

import type { Horse, StallConfiguration, TransportAsset } from "@prisma/client";

type HorseWithCompat = Horse;

// Temperament compatibility matrix
// Returns: "compatible" | "needs_review" | "incompatible" | "unknown"
export function checkTemperamentCompatibility(horses: HorseWithCompat[]): "compatible" | "needs_review" | "incompatible" | "unknown" {
  if (horses.length < 2) return "compatible";

  const tempers = horses.map((h) => (h.temperament || "").toLowerCase());
  const hasUnknown = tempers.some((t) => !t);
  if (hasUnknown) return "unknown";

  // Aggressive markers — these don't auto-reject but require specialist review
  const aggressiveMarkers = ["hung dữ", "hiếu động", "dữ", "nhan nhẹ", "kích động"];
  // Calm markers
  const calmMarkers = ["hiền lành", "bình tĩnh", "ôn"];

  const hasAggressive = tempers.some((t) => aggressiveMarkers.some((m) => t.includes(m)));
  const hasCalm = tempers.some((t) => calmMarkers.some((m) => t.includes(m)));

  // If one aggressive + one calm (mixed) → needs review (not auto-incompatible)
  // If multiple aggressive → incompatible
  const aggressiveCount = tempers.filter((t) => aggressiveMarkers.some((m) => t.includes(m))).length;

  if (aggressiveCount >= 2) return "incompatible";
  if (aggressiveCount >= 1 && hasCalm) return "needs_review";
  if (aggressiveCount >= 1) return "needs_review";

  return "compatible";
}

// Check weight capacity for a stall configuration
export function checkWeightCapacity(
  horses: HorseWithCompat[],
  stallConfig: StallConfiguration
): { ok: boolean; combinedWeight: number; maxWeight: number | null; reason: string } {
  const combinedWeight = horses.reduce((s, h) => s + (h.weightKg || 0), 0);
  const maxWeight = stallConfig.maxCombinedWeightKg;

  // If no weight data on any horse
  const missingWeight = horses.filter((h) => h.weightKg == null);
  if (missingWeight.length > 0) {
    return {
      ok: false,
      combinedWeight,
      maxWeight,
      reason: `Chưa đủ dữ liệu cân nặng cho ${missingWeight.length} ngựa — không thể đánh giá tải trọng`,
    };
  }

  // If stall has no max weight configured → mark as needs verification
  if (maxWeight == null) {
    return {
      ok: false,
      combinedWeight,
      maxWeight,
      reason: "Giới hạn tải trọng chuồng chưa được cấu hình — cần quản trị viên xác minh",
    };
  }

  if (combinedWeight > maxWeight) {
    return {
      ok: false,
      combinedWeight,
      maxWeight,
      reason: `Tổng cân nặng ${combinedWeight}kg vượt giới hạn chuồng ${maxWeight}kg`,
    };
  }

  return { ok: true, combinedWeight, maxWeight, reason: `Tổng cân nặng ${combinedWeight}kg nằm trong giới hạn ${maxWeight}kg` };
}

// Check if any horse requires a separate stall (vet mandate)
export function checkSeparateStallRequirement(horses: HorseWithCompat[]): { ok: boolean; reason: string } {
  const requiring = horses.filter((h) => h.requiresSeparateStall);
  if (requiring.length > 0 && horses.length > 1) {
    return {
      ok: false,
      reason: `${requiring.map((h) => h.name).join(", ")} có yêu cầu thú y bắt buộc chuồng riêng — không thể ghép`,
    };
  }
  return { ok: true, reason: "" };
}

// Check if asset type supports the stall configuration
export function checkAssetTypeSupport(
  stallConfig: StallConfiguration,
  assetTypes: string[]
): { ok: boolean; reason: string } {
  const supportedTypes: string[] = (() => {
    try { return JSON.parse(stallConfig.supportedAssetTypes || "[]"); } catch { return []; }
  })();
  if (supportedTypes.length === 0) {
    return { ok: false, reason: "Cấu hình chuồng chưa khai báo loại phương tiện hỗ trợ" };
  }
  const hasMatch = assetTypes.some((t) => supportedTypes.includes(t));
  if (!hasMatch) {
    return { ok: false, reason: `Cấu hình chuồng không hỗ trợ loại phương tiện hiện có (${assetTypes.join(", ")})` };
  }
  return { ok: true, reason: "" };
}

// Full stall-sharing feasibility evaluation
export type StallFeasibilityResult = {
  status: "Khả dụng" | "Cần thẩm định" | "Không phù hợp" | "Chưa đủ dữ liệu";
  reasons: string[];
  stallConfig: StallConfiguration;
  adjustedCost: number; // cost after applying multiplier
};

export function evaluateStallFeasibility(
  horses: HorseWithCompat[],
  stallConfig: StallConfiguration,
  availableAssetTypes: string[],
  baseCostPerHorse: number
): StallFeasibilityResult {
  const reasons: string[] = [];
  let status: StallFeasibilityResult["status"] = "Khả dụng";

  // 1. Check horse count vs stall max
  if (horses.length > stallConfig.maxHorses) {
    return {
      status: "Không phù hợp",
      reasons: [`Số ngựa (${horses.length}) vượt sức chứa chuồng (tối đa ${stallConfig.maxHorses})`],
      stallConfig,
      adjustedCost: 0,
    };
  }

  // For single stall, only 1 horse — if request has more horses, they need multiple single stalls
  // But if horses.length < maxHorses, the stall can still be used (under-utilized)
  // For pair/triple, we need at least 2/3 horses to actually "share"
  if (stallConfig.maxHorses >= 2 && horses.length < 2) {
    return {
      status: "Không phù hợp",
      reasons: [`Cấu hình ${stallConfig.name} cần ít nhất 2 ngựa để ghép — chỉ có ${horses.length} ngựa trong đơn`],
      stallConfig,
      adjustedCost: 0,
    };
  }

  // 2. Check asset type support
  const assetCheck = checkAssetTypeSupport(stallConfig, availableAssetTypes);
  if (!assetCheck.ok) {
    return {
      status: "Không phù hợp",
      reasons: [assetCheck.reason],
      stallConfig,
      adjustedCost: 0,
    };
  }

  // 3. Check separate stall requirement (vet mandate)
  const separateCheck = checkSeparateStallRequirement(horses);
  if (!separateCheck.ok) {
    return {
      status: "Không phù hợp",
      reasons: [separateCheck.reason],
      stallConfig,
      adjustedCost: 0,
    };
  }

  // 4. Check weight capacity
  const weightCheck = checkWeightCapacity(horses, stallConfig);
  if (!weightCheck.ok) {
    // Missing weight data → "Chưa đủ dữ liệu"
    if (weightCheck.reason.includes("Chưa đủ dữ liệu")) {
      status = "Chưa đủ dữ liệu";
      reasons.push(weightCheck.reason);
    } else if (weightCheck.reason.includes("chưa được cấu hình")) {
      status = "Chưa đủ dữ liệu";
      reasons.push(weightCheck.reason);
    } else {
      // Exceeded weight → not feasible
      return {
        status: "Không phù hợp",
        reasons: [weightCheck.reason],
        stallConfig,
        adjustedCost: 0,
      };
    }
  } else {
    reasons.push(weightCheck.reason);
  }

  // 5. Check temperament compatibility (only for shared stalls)
  if (stallConfig.maxHorses >= 2) {
    const temperCheck = checkTemperamentCompatibility(horses);
    if (temperCheck === "incompatible") {
      return {
        status: "Không phù hợp",
        reasons: ["Tính khí các ngựa không tương thích — nguy cơ xung đột cao"],
        stallConfig,
        adjustedCost: 0,
      };
    } else if (temperCheck === "needs_review") {
      status = status === "Chưa đủ dữ liệu" ? "Chưa đủ dữ liệu" : "Cần thẩm định";
      reasons.push("Tính khí có yếu tố cần thẩm định (hiếu động/nhạy cảm) — chuyên viên cần xem xét");
    } else if (temperCheck === "unknown") {
      status = "Chưa đủ dữ liệu";
      reasons.push("Chưa đủ dữ liệu tính khí của một hoặc nhiều ngựa");
    } else {
      reasons.push("Tính khí các ngựa tương thích");
    }
  }

  // 6. If stall always requires specialist review
  if (stallConfig.requiresSpecialistReview && status === "Khả dụng") {
    status = "Cần thẩm định";
    reasons.push("Cấu hình chuồng này yêu cầu chuyên viên thẩm định theo quy định");
  }

  // Compute adjusted cost
  const adjustedCost = Math.round(baseCostPerHorse * stallConfig.priceMultiplierPerHorse * horses.length);

  return { status, reasons, stallConfig, adjustedCost };
}

// Ride-sharing feasibility check
export type RideShareFeasibilityResult = {
  status: "Khả dụng" | "Cần thẩm định" | "Không phù hợp" | "Chưa đủ dữ liệu";
  reasons: string[];
  compatibleRequests: any[];
};

export function evaluateRideShareFeasibility(
  currentRequest: {
    requestId: string;
    originLocationId: string;
    destinationLocationId: string;
    scheduledDepartureDate: Date;
    scheduledArrivalDate: Date;
    horses: { horse: HorseWithCompat }[];
    status: string;
  },
  otherRequests: any[]
): RideShareFeasibilityResult {
  const reasons: string[] = [];
  let status: RideShareFeasibilityResult["status"] = "Khả dụng";

  // Find compatible requests: same origin + destination, overlapping time window (±24h)
  const compatible = otherRequests.filter((other) => {
    if (other.requestId === currentRequest.requestId) return false;
    if (other.originLocationId !== currentRequest.originLocationId) return false;
    if (other.destinationLocationId !== currentRequest.destinationLocationId) return false;

    // Time window: departure within 24h of each other
    const timeDiff = Math.abs(
      new Date(other.scheduledDepartureDate).getTime() - currentRequest.scheduledDepartureDate.getTime()
    );
    if (timeDiff > 24 * 60 * 60 * 1000) return false;

    // Both must be in a valid status for ride-share
    if (!["Đã phê duyệt", "Đang thẩm định", "Đã gửi"].includes(other.status)) return false;

    return true;
  });

  if (compatible.length === 0) {
    return {
      status: "Không phù hợp",
      reasons: ["Không có đơn nào cùng tuyến và thời gian phù hợp để ghép chuyến"],
      compatibleRequests: [],
    };
  }

  // Check combined horse count doesn't exceed max asset capacity (4 horses per flight slot)
  const currentHorseCount = currentRequest.horses.length;
  for (const other of compatible) {
    const otherHorseCount = other.horses?.length || 0;
    const totalHorses = currentHorseCount + otherHorseCount;
    if (totalHorses > 4) {
      reasons.push(`Đơn ${other.competitionName || other.requestId.slice(-8)}: tổng ${totalHorses} ngựa vượt sức chứa phương tiện (tối đa 4)`);
      continue;
    }

    // Check temperament compatibility across requests
    const allHorses = [
      ...currentRequest.horses.map((h) => h.horse),
      ...(other.horses || []).map((h: any) => h.horse),
    ];
    const temperCheck = checkTemperamentCompatibility(allHorses);
    if (temperCheck === "incompatible") {
      reasons.push(`Đơn ${other.competitionName || other.requestId.slice(-8)}: tính khí ngựa không tương thích`);
      continue;
    } else if (temperCheck === "needs_review") {
      status = "Cần thẩm định";
      reasons.push(`Đơn ${other.competitionName || other.requestId.slice(-8)}: cần thẩm định tính khí giữa các ngựa`);
    } else if (temperCheck === "unknown") {
      status = "Chưa đủ dữ liệu";
      reasons.push(`Đơn ${other.competitionName || other.requestId.slice(-8)}: thiếu dữ liệu tính khí`);
    }

    reasons.push(`Có thể ghép với đơn ${other.competitionName || other.requestId.slice(-8)} — cùng tuyến, thời gian phù hợp, sức chứa đủ`);
  }

  const feasibleCompatible = compatible.filter((other) => {
    const totalHorses = currentHorseCount + (other.horses?.length || 0);
    return totalHorses <= 4;
  });

  if (feasibleCompatible.length === 0) {
    return {
      status: "Không phù hợp",
      reasons: ["Tất cả đơn cùng tuyến đều vượt sức chứa khi ghép"],
      compatibleRequests: [],
    };
  }

  return { status, reasons, compatibleRequests: feasibleCompatible };
}
