import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth";
import {
  evaluateStallFeasibility,
  evaluateRideShareFeasibility,
  type StallFeasibilityResult,
} from "@/lib/stall-business-rules";

// GET /api/transport-requests/[id]/options — propose up to 3 feasible options
// with stall configuration feasibility and ride-share evaluation
export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "Chưa đăng nhập" }, { status: 401 });
  const { id } = await params;

  const request = await db.transportRequest.findUnique({
    where: { requestId: id },
    include: {
      horses: { include: { horse: true } },
      origin: true,
      destination: true,
      optionSelections: { include: { option: true } },
    },
  });
  if (!request) return NextResponse.json({ error: "Không tìm thấy đơn" }, { status: 404 });
  if (!["CUSTOMER", "LOGISTICS_MANAGER"].includes(session.roleId)) {
    return NextResponse.json({ error: "Không có quyền xem phương án và báo giá" }, { status: 403 });
  }
  if (session.roleId === "CUSTOMER" && request.customerId !== session.userId) {
    return NextResponse.json({ error: "Không có quyền truy cập" }, { status: 403 });
  }

  const allOptions = await db.transportOption.findMany({ where: { isActive: true } });
  const allStallConfigs = await db.stallConfiguration.findMany({ where: { isActive: true } });
  const assets = await db.transportAsset.findMany({ where: { status: "Sẵn sàng" } });
  const availableAssetTypes = [...new Set(assets.map((a) => a.type))];

  const totalHorses = request.horses.length;
  const horses = request.horses.map((h) => h.horse);
  const originCountry = request.origin.countryCode;
  const destCountry = request.destination.countryCode;
  const isInternational = originCountry !== destCountry;

  const daysUntilDeparture = Math.max(
    0,
    Math.ceil((request.scheduledDepartureDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24))
  );

  // Find other requests for ride-share evaluation (same origin/dest, overlapping time)
  const otherRequests = await db.transportRequest.findMany({
    where: {
      requestId: { not: id },
      originLocationId: request.originLocationId,
      destinationLocationId: request.destinationLocationId,
      status: { in: ["Đã phê duyệt", "Đang thẩm định", "Đã gửi"] },
    },
    include: { horses: { include: { horse: true } } },
  });

  // Evaluate ride-share feasibility
  const rideShareResult = evaluateRideShareFeasibility(
    {
      requestId: request.requestId,
      originLocationId: request.originLocationId,
      destinationLocationId: request.destinationLocationId,
      scheduledDepartureDate: request.scheduledDepartureDate,
      scheduledArrivalDate: request.scheduledArrivalDate,
      horses: request.horses,
      status: request.status,
    },
    otherRequests
  );

  // Evaluate each transport option
  const evaluated = allOptions.map((opt) => {
    let feasible = true;
    const reasons: string[] = [];

    // Air requires international
    if (opt.mode === "AIR" && !isInternational) {
      feasible = false;
      reasons.push("Chuyến bay chỉ áp dụng vận chuyển quốc tế");
    }

    // Check time feasibility
    if (daysUntilDeparture > 0 && opt.estTransitHours / 24 > daysUntilDeparture) {
      feasible = false;
      reasons.push("Không đủ thời gian trước ngày khởi hành dự kiến");
    }

    // Check capacity (max 4 horses per flight)
    if (totalHorses > 4 && opt.mode === "AIR") {
      reasons.push("Cần chia nhiều container do vượt sức chứa một chuyến");
    }

    // Compute base quote items
    const baseCost = opt.baseCost * totalHorses;
    const mandatoryDocsCost = isInternational ? 350000 : 0;
    const quarantineCost = isInternational ? 500000 : 0;

    // Evaluate stall configurations for this option
    const stallConfigsEval: StallFeasibilityResult[] = allStallConfigs.map((sc) => {
      return evaluateStallFeasibility(horses, sc, availableAssetTypes, opt.baseCost);
    });

    // Compute the best (recommended) stall config — prefer feasible, then lowest cost
    const feasibleStalls = stallConfigsEval.filter((s) => s.status === "Khả dụng" || s.status === "Cần thẩm định");
    const bestStall = feasibleStalls.length > 0
      ? feasibleStalls.sort((a, b) => a.adjustedCost - b.adjustedCost)[0]
      : stallConfigsEval[0];

    const stallCost = bestStall ? bestStall.adjustedCost : Math.round(baseCost * 0.15 * 100) / 100;
    // Use USD rounding (2 decimals) instead of integer VND
    const mandatoryDocsCostUSD = isInternational ? 350 : 0;
    const quarantineCostUSD = isInternational ? 500 : 0;
    const total = Math.round((baseCost + stallCost + mandatoryDocsCostUSD + quarantineCostUSD) * 100) / 100;

    return {
      option: opt,
      feasible,
      reasons: reasons.length ? reasons : ["Đáp ứng các điều kiện hiện tại, thời gian dự kiến phù hợp, chi phí hợp lý."],
      recommended: false,
      stallConfigs: stallConfigsEval.map((s) => ({
        configId: s.stallConfig.configId,
        name: s.stallConfig.name,
        maxHorses: s.stallConfig.maxHorses,
        description: s.stallConfig.description,
        priceMultiplierPerHorse: s.stallConfig.priceMultiplierPerHorse,
        pros: (() => { try { return JSON.parse(s.stallConfig.pros || "[]"); } catch { return []; } })(),
        cons: (() => { try { return JSON.parse(s.stallConfig.cons || "[]"); } catch { return []; } })(),
        risks: (() => { try { return JSON.parse(s.stallConfig.risks || "[]"); } catch { return []; } })(),
        status: s.status,
        reasons: s.reasons,
        adjustedCost: s.adjustedCost,
        // Dimensions
        lengthCm: s.stallConfig.lengthCm,
        widthCm: s.stallConfig.widthCm,
        heightCm: s.stallConfig.heightCm,
        basePriceUSD: s.stallConfig.basePriceUSD,
        pricingUnit: s.stallConfig.pricingUnit,
        maxCombinedWeightKg: s.stallConfig.maxCombinedWeightKg,
      })),
      bestStallConfigId: bestStall?.stallConfig.configId || null,
      // Add-on services available for this option (USD pricing)
      addOnServices: [
        { id: "vet-escort", name: "Thú y đi kèm suốt tuyến", description: "Bác sĩ thú y theo hộ tặc suốt hành trình, theo dõi sức khỏe ngựa", unitPrice: 850, unit: "chuyến", category: "CARE" },
        { id: "groom-service", name: "Dịch vụ chăm sóc & dắt ngựa", description: "Nhân viên chăm sóc, dắt ngựa tại điểm dừng và bàn giao", unitPrice: 450, unit: "chuyến", category: "CARE" },
        { id: "extra-insurance", name: "Bảo hiểm vận chuyển bổ sung", description: "Bảo hiểm giá trị ngựa đua trong suốt quá trình vận chuyển", unitPrice: 320, unit: "ngựa", category: "INSURANCE" },
        { id: "express-clearance", name: "Thông quan ưu tiên", description: "Xử lý hải quan ưu tiên, giảm thời gian chờ tại cảng", unitPrice: 280, unit: "chuyến", category: "TRANSIT" },
        { id: "special-feeding", name: "Khẩu phần ăn đặc biệt", description: "Thức ăn và thực đơn đặc biệt theo yêu cầu chăm sóc", unitPrice: 150, unit: "ngựa", category: "CARE" },
      ],
      quote: {
        items: [
          { name: `Phương án vận chuyển chính (${opt.name})`, feeType: "BASE", amount: baseCost, quantity: 1, unitPrice: opt.baseCost, includedInBase: true },
          { name: `Cấu hình chuồng: ${bestStall?.stallConfig.name || "Đơn chuẩn"}`, feeType: "STALL", amount: stallCost, quantity: totalHorses, unitPrice: bestStall ? Math.round(opt.baseCost * bestStall.stallConfig.priceMultiplierPerHorse * 100) / 100 : 0, includedInBase: false },
          ...(isInternational ? [{ name: "Chi phí giấy tờ kiểm dịch bắt buộc", feeType: "MANDATORY", amount: mandatoryDocsCostUSD, quantity: 1, unitPrice: mandatoryDocsCostUSD, includedInBase: false }] : []),
          ...(isInternational ? [{ name: "Phí kiểm dịch lưu giữ", feeType: "MANDATORY", amount: quarantineCostUSD, quantity: 1, unitPrice: quarantineCostUSD, includedInBase: false }] : []),
        ],
        total,
      },
      rideShare: {
        status: rideShareResult.status,
        reasons: rideShareResult.reasons,
        compatibleCount: rideShareResult.compatibleRequests.length,
        compatibleRequests: rideShareResult.compatibleRequests.map((r) => ({
          requestId: r.requestId,
          competitionName: r.competitionName,
          horseCount: r.horses?.length || 0,
          departureDate: r.scheduledDepartureDate,
        })),
      },
    };
  });

  const feasibleOptions = evaluated.filter((e) => e.feasible);
  // Rank: safety/time first, then cost
  feasibleOptions.sort((a, b) => {
    const aTime = a.option.estTransitHours;
    const bTime = b.option.estTransitHours;
    if (aTime !== bTime) return aTime - bTime;
    return a.quote.total - b.quote.total;
  });

  // Mark recommended (first), limit to 3
  const top = feasibleOptions.slice(0, 3);
  if (top[0]) top[0].recommended = true;

  const infeasible = evaluated.filter((e) => !e.feasible);

  return NextResponse.json({
    options: top,
    lockedOptions: infeasible,
    selectedSelection: request.optionSelections.find((selection) => selection.isSelected) || null,
    request: {
      id: request.requestId,
      totalHorses,
      isInternational,
      daysUntilDeparture,
      origin: request.origin.name,
      destination: request.destination.name,
      horses: horses.map((h) => ({
        horseId: h.horseId,
        name: h.name,
        weightKg: h.weightKg,
        heightCm: h.heightCm,
        temperament: h.temperament,
        requiresSeparateStall: h.requiresSeparateStall,
        transportExperience: h.transportExperience,
        vetNotes: h.vetNotes,
      })),
    },
  });
}

// POST — save selection + compute final quote with backend-verified business rules
export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "Chưa đăng nhập" }, { status: 401 });
  const { id } = await params;

  const request = await db.transportRequest.findUnique({
    where: { requestId: id },
    include: {
      horses: { include: { horse: true } },
      origin: true,
      destination: true,
      optionSelections: { where: { isSelected: true } },
    },
  });
  if (!request) return NextResponse.json({ error: "Không tìm thấy đơn" }, { status: 404 });
  if (session.roleId !== "CUSTOMER") {
    return NextResponse.json({ error: "Chỉ khách hàng mới được chọn phương án và báo giá" }, { status: 403 });
  }
  if (request.customerId !== session.userId) {
    return NextResponse.json({ error: "Không có quyền" }, { status: 403 });
  }
  if (request.selectedOptionId || request.optionSelections.length > 0) {
    return NextResponse.json({ error: "Phương án đã được xác nhận và không thể chỉnh sửa" }, { status: 409 });
  }
  if (!["Nháp", "Trả lại bổ sung"].includes(request.status)) {
    return NextResponse.json({ error: "Không thể thay đổi lựa chọn ở trạng thái này" }, { status: 409 });
  }

  const { optionId, stallConfigId, rideShareEnabled, addOns, escortCount } = await req.json();
  const option = await db.transportOption.findUnique({ where: { optionId } });
  if (!option) return NextResponse.json({ error: "Phương án không tồn tại" }, { status: 404 });

  // Verify stall config exists and re-evaluate feasibility at backend
  const stallConfig = stallConfigId ? await db.stallConfiguration.findUnique({ where: { configId: stallConfigId } }) : null;
  const horses = request.horses.map((h) => h.horse);
  const assets = await db.transportAsset.findMany({ where: { status: "Sẵn sàng" } });
  const availableAssetTypes = [...new Set(assets.map((a) => a.type))];

  let feasibilityStatus = "Khả dụng";
  let feasibilityReasons: string[] = [];

  if (stallConfig) {
    const stallEval = evaluateStallFeasibility(horses, stallConfig, availableAssetTypes, option.baseCost);
    feasibilityStatus = stallEval.status;
    feasibilityReasons = stallEval.reasons;

    // Backend rejects "Không phù hợp" — customer cannot select an infeasible stall
    if (stallEval.status === "Không phù hợp") {
      return NextResponse.json({
        error: "Cấu hình chuồng không khả thi",
        reasons: stallEval.reasons,
        status: stallEval.status,
      }, { status: 400 });
    }
  } else {
    return NextResponse.json({ error: "Vui lòng chọn cấu hình chuồng" }, { status: 400 });
  }

  // Clear previous selections
  await db.requestOptionSelection.deleteMany({ where: { requestId: id } });
  await db.quoteItem.deleteMany({ where: { requestId: id } });

  const totalHorses = horses.length;
  const baseCost = Math.round(option.baseCost * totalHorses * 100) / 100;
  const stallUnitPrice = Math.round(option.baseCost * stallConfig.priceMultiplierPerHorse * 100) / 100;
  const stallCost = Math.round(stallUnitPrice * totalHorses * 100) / 100;
  const isInternational = request.origin.countryCode !== request.destination.countryCode;
  const mandatoryDocsCost = isInternational ? 350 : 0;
  const quarantineCost = isInternational ? 500 : 0;

  // Add-on costs — backend re-calculates from addOn data (doesn't trust frontend amount)
  // Each addOn: { id, name, unitPrice, quantity, unit }
  const addOnList: { id: string; name: string; unitPrice: number; quantity: number; unit: string; amount: number }[] = Array.isArray(addOns) ? addOns : [];
  // Backend recalculates amount = unitPrice × quantity for each add-on
  const verifiedAddOns = addOnList.map((a) => ({
    ...a,
    amount: Math.round((a.unitPrice || 0) * (a.quantity || 1) * 100) / 100,
  }));
  const addOnCost = Math.round(verifiedAddOns.reduce((s, a) => s + a.amount, 0) * 100) / 100;
  const total = Math.round((baseCost + stallCost + mandatoryDocsCost + quarantineCost + addOnCost) * 100) / 100;

  const selection = await db.requestOptionSelection.create({
    data: {
      requestId: id,
      optionId,
      isSelected: true,
      stallConfig: stallConfig.name,
      stallConfigId: stallConfig.configId,
      rideShareEnabled: !!rideShareEnabled,
      feasibilityStatus,
      feasibilityReasons: JSON.stringify(feasibilityReasons),
      addOns: verifiedAddOns.length > 0 ? JSON.stringify(verifiedAddOns) : null,
      escortCount: escortCount || null,
      quotedTotal: total,
    },
  });

  // Create quote items (USD amounts)
  await db.quoteItem.createMany({
    data: [
      { requestId: id, optionId, name: `Phương án vận chuyển chính (${option.name})`, feeType: "BASE", amount: baseCost, includedInBase: true, status: "Đã xác nhận", note: `Đơn giá: USD ${option.baseCost.toFixed(2)} × ${totalHorses} ngựa` },
      { requestId: id, optionId, name: `Cấu hình chuồng: ${stallConfig.name}`, feeType: "STALL", amount: stallCost, includedInBase: false, status: feasibilityStatus === "Khả dụng" ? "Đã xác nhận" : "Chờ xác nhận", note: `Đơn giá: USD ${stallUnitPrice.toFixed(2)} × ${totalHorses} ngựa` },
      ...(isInternational ? [{ requestId: id, optionId, name: "Chi phí giấy tờ kiểm dịch bắt buộc", feeType: "MANDATORY", amount: mandatoryDocsCost, includedInBase: false, status: "Đã xác nhận" as const, note: "Phí cố định" }] : []),
      ...(isInternational ? [{ requestId: id, optionId, name: "Phí kiểm dịch lưu giữ", feeType: "MANDATORY", amount: quarantineCost, includedInBase: false, status: "Đã xác nhận" as const, note: "Phí cố định" }] : []),
      ...verifiedAddOns.map((a) => ({ requestId: id, optionId, name: a.name, feeType: "ADDON" as const, amount: a.amount, includedInBase: false, status: "Chờ xác nhận" as const, note: `Đơn giá: USD ${a.unitPrice.toFixed(2)} × ${a.quantity} ${a.unit}` })),
    ],
  });

  await db.transportRequest.update({
    where: { requestId: id },
    data: { estimatedAmount: total, selectedOptionId: optionId },
  });

  await db.auditLog.create({
    data: {
      userId: session.userId,
      requestId: id,
      action: "Chọn phương án vận chuyển",
      details: `Đã chọn: ${option.name}, chuồng: ${stallConfig.name}, ghép chuyến: ${rideShareEnabled ? "Có" : "Không"}, trạng thái khả thi: ${feasibilityStatus}, tổng dự kiến: ${total.toLocaleString("vi-VN")}đ`,
    },
  });

  return NextResponse.json({
    selection,
    total,
    feasibilityStatus,
    feasibilityReasons,
  });
}
